"""Offline campaign CLI; JSON stdin/stdout, diagnostics on stderr."""
import json
import math
from pathlib import Path
import sys
sys.path.insert(0, str(Path(__file__).resolve().parent / "src"))
from eywa.offline import execute

def pairs(items):
    d = {}
    for key, value in items:
        if key in d: raise ValueError("duplicate key")
        d[key] = value
    return d

def main():
    try:
        raw = sys.stdin.buffer.read(64 * 1024 * 1024 + 1)
        if len(raw) > 64 * 1024 * 1024: raise ValueError("input cap")
        def bad(value): raise ValueError("nonfinite")
        def finite(value):
            result = float(value)
            if not math.isfinite(result): raise ValueError("nonfinite")
            return result
        request = json.loads(raw.decode("utf-8"), object_pairs_hook=pairs, parse_constant=bad, parse_float=finite)
        if not isinstance(request, dict): raise ValueError("root is not an object")
    except (ValueError, UnicodeError, RecursionError):
        result = {"error": "INVALID_INPUT"}
    else:
        result = execute(request)
    json.dump(result, sys.stdout, ensure_ascii=True, separators=(",", ":"), allow_nan=False)
    sys.stdout.write("\n")
if __name__ == "__main__": main()
"""Guarded, exact minimum-cost replay setup."""
from collections import deque
import heapq
import json


def BFS(transition_dict, target_state, initial="INITIAL"):
    """Legacy unweighted helper; campaign preparation uses StateMachine."""
    queue = deque([(initial, [])])
    visited = {initial}
    while queue:
        state, sequence = queue.popleft()
        if state == target_state:
            return sequence
        for (source, command), destination in transition_dict.items():
            if source == state and destination not in visited:
                visited.add(destination)
                queue.append((destination, sequence + [command]))
    return None


class StateMachine:
    def __init__(self, machine):
        self.states = {name: index for index, name in enumerate(machine["states"])}
        self.initial = self.states[machine["initial"]]
        self.state_param = machine["state_param"]
        self.message_param = machine["message_param"]
        self.forward = [[] for _ in self.states]
        self.reverse = [[] for _ in self.states]
        self.guards = []
        guard_ids = {}
        for transition in machine["transitions"]:
            guard = transition["when"]
            guard_id = -1
            if guard is not None:
                key = json.dumps(guard, sort_keys=True, ensure_ascii=True, separators=(",", ":"))
                if key not in guard_ids:
                    guard_ids[key] = len(self.guards)
                    self.guards.append(guard)
                guard_id = guard_ids[key]
            source = self.states[transition["from"]]
            destination = self.states[transition["to"]]
            edge = (source, destination, transition["command"], transition["cost"], guard_id)
            self.forward[source].append(edge)
            self.reverse[destination].append(edge)
        for edges in self.forward:
            edges.sort(key=lambda edge: edge[2])

    def prepare(self, target, evaluate_guard):
        """Return (cost, commands), or None.

        Reverse Dijkstra minimizes (cost,hops). Greedy reconstruction along
        optimal edges then minimizes the entire command sequence, without
        copying O(path length) tuples at every relaxation. Positive edge costs
        ensure reconstruction strictly descends the distances, even in cycles.
        """
        target = self.states[target]
        if target == self.initial:
            return 0, []
        enabled_cache = {-1: True}

        def enabled(guard):
            if guard not in enabled_cache:
                enabled_cache[guard] = bool(evaluate_guard(guard))
            return enabled_cache[guard]

        distances = [None] * len(self.states)
        distances[target] = (0, 0)
        queue = [(0, 0, target)]
        while queue:
            cost, hops, state = heapq.heappop(queue)
            if distances[state] != (cost, hops):
                continue
            if state == self.initial:
                break
            for source, _, _, weight, guard in self.reverse[state]:
                if not enabled(guard):
                    continue
                candidate = (cost + weight, hops + 1)
                if distances[source] is None or candidate < distances[source]:
                    distances[source] = candidate
                    heapq.heappush(queue, (*candidate, source))
        else:
            return None

        total = distances[self.initial][0]
        commands = []
        state = self.initial
        while state != target:
            cost, hops = distances[state]
            for _, destination, command, weight, guard in self.forward[state]:
                distance = distances[destination]
                if (distance is not None and distance[0] + weight == cost
                        and distance[1] + 1 == hops and enabled(guard)):
                    commands.append(command)
                    state = destination
                    break
            else:
                raise AssertionError("shortest-path reconstruction")
        return total, commands


def prepare(machine, target, assignment, predicate):
    """Convenience interface for a raw machine and a (guard, inputs) evaluator."""
    compiled = machine if isinstance(machine, StateMachine) else StateMachine(machine)
    return compiled.prepare(target, lambda index: predicate(compiled.guards[index], assignment))
